}

func submitSearch(t *testing.T, m Model, query string) (Model, tea.Cmd) {
 t.Helper()
 u, _ := m.Update(tea.KeyMsg{Type:tea.KeyRunes, Runes:[]rune("s")})
 m = u.(Model)
 m.search.SetValue(query)
 u, cmd := m.Update(tea.KeyMsg{Type:tea.KeyEnter})
